import{_ as l,l as s,o as t,c as n,v as e,p as o,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"虚表与动态分派","description":"","frontmatter":{"title":"虚表与动态分派","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vtable-dispatch.md","filePath":"cs/vtable-dispatch.md","lastUpdated":1789023840000}'),c={name:"cs/vtable-dispatch.md"};function u(_,a,m,f,b,v){const i=s("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="虚表与动态分派" tabindex="-1">虚表与动态分派 <a class="header-anchor" href="#虚表与动态分派" aria-label="Permalink to &quot;虚表与动态分派&quot;">​</a></h1><div class="epigraph"><p>对象头指向方法表；调用 `p-&gt;f()` 变成 `p-&gt;vptr[i](p)`。单继承表简单，多继承与接口要 thunk 或 Itanium 式偏移。</p><footer>—— 据 Ellis and Stroustrup, The Annotated C++ Reference Manual；Itanium C++ ABI；对照[内联缓存](/cs/inline-caching) 与[类型类](/cs/typeclass-dictionary) 整理</footer></div><p>上一课<a href="/cs/trampolining">蹦床</a> 是函数式控制。OOP：动态分派。缺口是 <strong>vtable</strong> 布局。反射下一课。主干类型课有 overload；这里是运行时表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态重载在编译期选。虚函数：接收者运行时类。实现：每类一张表，槽位按声明序。缺口是<strong>索引与 this 调整</strong>，不是 IC 状态机。</p><p>单继承：子类表前缀兼容。多继承：子对象偏移，thunk 调 this。接口：另表或 ITT。</p><h3 id="虚表不是类型类字典的复制粘贴" tabindex="-1">虚表不是类型类字典的复制粘贴 <a class="header-anchor" href="#虚表不是类型类字典的复制粘贴" aria-label="Permalink to &quot;虚表不是类型类字典的复制粘贴&quot;">​</a></h3><p>字典常在调用处；vtable 在对象上，支持未知子类。IC 可把虚调用投机成直跳。</p><p><span class="marginnote">ARM C++ / Itanium ABI。Stroustrup。本课 C++ 模型；Java 接口表类似。不写 COM 全部。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端：每个虚方法一个槽。构造函数写 vptr。去虚：CHA 或具体类型已知则直调，可内联。JIT 用 CHA+依赖记录，类加载则去优化。</p>',11)),(t(),o(h,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20VP%5B%22vptr%22%5D%0A%20%20VP%20--%3E%20SLOT%5B%22%E6%A7%BD%20i%22%5D%0A%20%20SLOT%20--%3E%20F%5B%22%E6%96%B9%E6%B3%95%20%2B%20this%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与<a href="/cs/calling-convention-impl">调用约定</a>：this 是隐式参数。与 GC：vptr 不是用户字段但要跟对象走。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多重继承菱形：虚基类更复杂。不要手填 vptr 当安全。Swift/Rust trait 对象：胖指针 {data, vtable}，表不在对象头——对照字典。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写反射。后课默认：开世界方法用 vtable。下一课反射与元数据。</p><p>也不把虚表当数据库视图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>虚调用：vptr 索引 + this。</li><li>多继承要偏移 thunk。</li><li>去虚+IC 把动态变静态。</li><li>出处：Itanium C++ ABI；Ellis and Stroustrup；对照 Hölzle IC。</li></ul>',8))])}const C=l(c,[["render",u]]);export{A as __pageData,C as default};
